-- =============================================================================
-- Seed 99 : INSTANTANÉ des données de production (généré — ne pas éditer).
-- -----------------------------------------------------------------------------
-- Régénérer : node scripts/snapshot-db.mjs   ·   Vérifier : --check
-- Upsert sur clés naturelles (slug / code) : idempotent. Reconstruction d'une
-- base = migrations puis ce fichier, rien d'autre (les seeds de history/ sont
-- périmés). Exclus : corrections (données de lecteurs).
-- Lignes :
--   sectors                  19
--   dimensions               10
--   dimension_groups         1
--   dimension_group_members  3
--   indicators               54
--   dimension_gates          3
--   sources                  59
--   source_tier_config       4
--   evidence_nature_config   4
--   scoring_params           11
--   value_profiles           4
--   profile_weights          40
--   entities                 2020
--   evidence                 2019
--   political_groups         18
--   civic_votes              4
--   civic_positions          35
--   disclosure_regimes       7
--   indicator_regimes        13
--   entity_regimes           116
--   indicator_sectors        33
--   sector_dimension_weights 5
--   obligation_exemptions    3
--   entity_ownership_sources 1558
-- =============================================================================

begin;

-- Secteurs
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  animal_relevant = excluded.animal_relevant,
  wap_relevant = excluded.wap_relevant,
  inv_relevant = excluded.inv_relevant,
  plastic_relevant = excluded.plastic_relevant,
  water_relevant = excluded.water_relevant;

-- Piliers (dimensions)
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  default_weight = excluded.default_weight,
  display_order = excluded.display_order;

-- Méta-scores
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  display_order = excluded.display_order;

-- Membres des méta-scores
on conflict (group_id, dimension_id) do update set
  weight = excluded.weight;

-- Indicateurs
on conflict (code) do update set
  dimension_id = excluded.dimension_id,
  name = excluded.name,
  kind = excluded.kind,
  direction = excluded.direction,
  sector_specific = excluded.sector_specific,
  applies_to_sector_id = excluded.applies_to_sector_id,
  weight = excluded.weight,
  unit = excluded.unit,
  methodology = excluded.methodology,
  presence_only = excluded.presence_only,
  jurisdiction = excluded.jurisdiction,
  complementary = excluded.complementary,
  group_level = excluded.group_level,
  disclosure = excluded.disclosure;

-- Pertinence sectorielle par liste
on conflict (indicator_id, sector_id) do nothing;

-- Matérialité sectorielle
on conflict (sector_id, dimension_id) do update set
  multiplier = excluded.multiplier,
  note = excluded.note;

-- Gates (plafonds de pilier)
on conflict (dimension_id) do update set
  gate_indicator_id = excluded.gate_indicator_id,
  default_ceiling = excluded.default_ceiling,
  notes = excluded.notes;

-- Sources
on conflict (code) do update set
  name = excluded.name,
  tier = excluded.tier,
  publisher = excluded.publisher,
  url = excluded.url,
  description = excluded.description;

-- Config méthodo : tiers de source
on conflict (tier) do update set
  evidence_weight = excluded.evidence_weight,
  max_confidence = excluded.max_confidence,
  can_penalize_alone = excluded.can_penalize_alone,
  min_score_floor_alone = excluded.min_score_floor_alone,
  notes = excluded.notes;

-- Config méthodo : nature des preuves
on conflict (nature) do update set
  score_multiplier = excluded.score_multiplier,
  max_score_without_result = excluded.max_score_without_result,
  notes = excluded.notes;

-- Config méthodo : paramètres
on conflict (key) do update set
  value = excluded.value,
  description = excluded.description;

-- Profils de valeurs
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  is_default = excluded.is_default;

-- Poids des profils
on conflict (profile_id, dimension_id) do update set
  weight = excluded.weight;

-- Entités (résolution : identifiants officiels)
on conflict (slug) do update set
  legal_name = excluded.legal_name,
  display_name = excluded.display_name,
  lei = excluded.lei,
  siren = excluded.siren,
  country = excluded.country,
  sector_id = excluded.sector_id,
  is_brand = excluded.is_brand,
  animal_free = excluded.animal_free;

-- Entités : chaîne de détention (marque → groupe)
update entities e set parent_id = p.id, ownership_pct = v.pct
