insert into indicators (code, dimension_id, name, kind, direction, sector_specific, applies_to_sector_id, weight, unit, methodology, presence_only, jurisdiction, complementary, group_level, disclosure) values
  ('ANI_ANGORA_MOHAIR', (select id from dimensions where code = 'ANI'), 'Angora & mohair', 'categorical', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 0.6, 'policy', 'Ban angora / mohair certifié RMS : none/policy/ban-or-RMS -> 0/0.5/1.', false, null, true, false, false),
  ('ANI_ANIMAL_FREE', (select id from dimensions where code = 'ANI'), 'Gamme sans intrant animal (100 % végétale)', 'binary', 'higher_better', false, null, 1, null, 'Absence totale d''intrant animal : meilleur résultat possible sur le pilier bien-être animal.', false, null, false, false, false),
  ('ANI_BBFAW_TIER', (select id from dimensions where code = 'ANI'), 'Bien-être animal (classement BBFAW)', 'ordinal', 'higher_better', false, null, 0.8, 'tier', 'Benchmark BBFAW tier 6..1 -> [0,1].', false, null, true, true, false),
  ('ANI_DOWN_RDS', (select id from dimensions where code = 'ANI'), 'Duvet responsable (sans plumage à vif)', 'categorical', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 0.7, 'policy', 'none/policy/RDS certifié -> 0/0.5/1.', false, null, true, false, false),
  ('ANI_EXOTIC_SKINS', (select id from dimensions where code = 'ANI'), 'Peaux exotiques', 'categorical', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 0.8, 'policy', 'none/policy/ban -> 0/0.5/1.', false, null, true, false, false),
  ('ANI_EXPLOITATION', (select id from dimensions where code = 'ANI'), 'Recours à l''exploitation animale', 'categorical', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 0, 'ceiling', 'PLAFOND du pilier. Sans intrant animal = 1 ; toute exploitation animale, même marginale = 0 (décision de l''éditeur, 11/10/2026). Inconnu : exploitation présumée.', false, null, false, false, false),
  ('ANI_FUR_FREE', (select id from dimensions where code = 'ANI'), 'Politique sans fourrure', 'binary', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 1, 'bool', 'Listé Fur Free Retailer / engagement public sans fourrure.', true, null, false, false, false),
  ('ANI_LEATHER_TRACE', (select id from dimensions where code = 'ANI'), 'Traçabilité & tannage du cuir', 'ordinal', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 0.9, 'level', 'Leather Working Group + traçabilité origine : aucun/certifié/traçé+certifié -> 0/0.5/1.', false, null, true, false, false),
  ('ANI_SLAUGHTER', (select id from dimensions where code = 'ANI'), 'Standards abattage & transport', 'ordinal', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 0.7, 'level', 'Standards de bien-être à l''abattage/transport : aucun/engagement/audité -> 0/0.5/1.', false, null, true, false, false),
  ('ANI_TESTING', (select id from dimensions where code = 'ANI'), 'Tests sur animaux', 'categorical', 'higher_better', true, (select id from sectors where code = 'beauty_fragrance'), 0.9, 'policy', 'Politique cosmétique : tests/aucun engagement/cruelty-free certifié -> 0/0.5/1.', false, null, true, false, false),
  ('ANI_WOOL_MULESING', (select id from dimensions where code = 'ANI'), 'Laine sans mulesing', 'categorical', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 0.8, 'policy', 'none/policy/certified (RWS/mulesing-free) -> 0/0.5/1.', false, null, true, false, false),
  ('ENV_CDP_CLIMATE', (select id from dimensions where code = 'ENV'), 'Note climat CDP', 'ordinal', 'higher_better', false, null, 1, 'grade', 'Lettre CDP A..D- mappée sur [0,1], puis percentile intra-secteur.', false, null, false, true, false),
  ('ENV_GHG_INTENSITY', (select id from dimensions where code = 'ENV'), 'Intensité carbone', 'quantitative', 'lower_better', false, null, 1, 'tCO2e/M€', 'Émissions / chiffre d''affaires, percentile inversé intra-secteur.', false, null, true, true, false),
  ('ENV_GHG_TREND', (select id from dimensions where code = 'ENV'), 'Évolution réelle des émissions (scopes 1, 2 et 3)', 'quantitative', 'lower_better', false, null, 1.5, '%/an', 'Rythme annuel moyen d''évolution des émissions totales publiées (scopes 1+2+3) entre l''année de référence et la dernière année : 1 si baisse de 4,2 % par an ou plus (trajectoire 1,5 °C SBTi), 0 si les émissions ne baissent pas, linéaire entre les deux.', false, null, true, true, false),
  ('ENV_GREENWASHING', (select id from dimensions where code = 'ENV'), 'Allégations environnementales trompeuses (décision d''une autorité)', 'categorical', 'higher_better', false, null, 1, 'controverse', 'Décision officielle d''une autorité de protection des consommateurs : amende pour allégations environnementales trompeuses = sévérité 0,8 ; engagements de retrait obtenus après enquête, sans sanction = 0,5. Absent : non pénalisé.', false, null, true, true, false),
  ('ENV_MATERIAL_CHANGE', (select id from dimensions where code = 'ENV'), 'Matières durables (Textile Exchange)', 'ordinal', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 1, 'rank', 'Material Change Index : rang -> percentile.', false, null, true, false, false),
  ('ENV_SBTI_VALIDATED', (select id from dimensions where code = 'ENV'), 'Objectifs climat validés (SBTi)', 'categorical', 'higher_better', false, null, 1, 'status', 'Objectif de court terme SBTi. Validé 1,5 °C = 1 ; validé (autre) = 0,6 ; engagement à fixer un objectif = 0,5 ; tous traités comme des engagements (Règle 3 : ×0,4, plafond 0,5). Engagement retiré = 0 (fait).', false, null, false, true, false),
  ('ENV_SCOPE3_DISCLOSED', (select id from dimensions where code = 'ENV'), 'Émissions indirectes (scope 3) publiées', 'binary', 'higher_better', false, null, 0.8, 'bool', 'Publication + couverture % des postes Scope 3 (CSRD ESRS E1).', false, null, true, true, true),
  ('ENV_TAXONOMY_CAPEX', (select id from dimensions where code = 'ENV'), 'Investissements alignés sur la taxonomie verte de l''UE', 'quantitative', 'higher_better', false, null, 1, '%', 'Part des investissements (CapEx) alignés sur la taxonomie verte de l''UE, publiée dans le rapport annuel audité (règlement (UE) 2020/852, art. 8 ; règlement délégué 2021/2178), sur le périmètre réglementaire des entités contrôlées. Valeur absolue : 30 % alignés = 0,30. Énergie et automobile seulement.', false, null, true, true, false),
  ('GEO_CONFLICT_TIES', (select id from dimensions where code = 'GEO'), 'Implication dans un conflit / une occupation', 'categorical', 'higher_better', false, null, 0.8, null, 'Implication matérielle documentée dans un conflit armé ou une occupation (base ONU OHCHR, décisions CIJ, actes attribuables). Faits institutionnels uniquement — jamais le boycott seul ni une opinion.', false, null, true, true, false),
  ('GEO_LOBBYING_ALIGN', (select id from dimensions where code = 'GEO'), 'Alignement du lobbying climat', 'categorical', 'higher_better', false, null, 0.8, 'score', 'Alignement du lobbying avec l''Accord de Paris (InfluenceMap/LobbyMap). Distinct de la transparence.', false, null, true, true, false),
  ('GEO_LOBBYING_SPEND', (select id from dimensions where code = 'GEO'), 'Dépenses de lobbying déclarées', 'quantitative', 'contextual', false, null, 0.4, '€', 'Montant déclaré HATVP/UE. Contextuel : affiché, non pénalisant en soi.', false, null, true, true, false),
  ('GEO_LOBBYING_TRANSP', (select id from dimensions where code = 'GEO'), 'Transparence du lobbying', 'binary', 'higher_better', false, null, 0.7, 'bool', 'Inscription HATVP / registre transparence UE (oui/non).', false, null, false, true, false),
  ('GEO_POL_FINANCING', (select id from dimensions where code = 'GEO'), 'Financement politique', 'quantitative', 'contextual', false, null, 0.4, '€', 'Données CNCCFP (structurellement pauvres en FR). Contextuel.', false, null, true, true, false),
  ('GEO_RUSSIA_EXIT', (select id from dimensions where code = 'GEO'), 'Sortie de Russie (depuis l''invasion de l''Ukraine)', 'categorical', 'higher_better', false, null, 1, 'status', 'maintien/réduction/suspension/retrait -> 0/0.4/0.7/1 (liste Yale CELI).', false, null, true, true, false),
  ('GOV_BCORP', (select id from dimensions where code = 'GOV'), 'Certification B Corp', 'binary', 'higher_better', false, null, 0.8, 'bool', 'Certification B Corp en vigueur (annuaire B Lab ; score B Impact ≥ 80). Absence non renseignée (jamais comptée 0).', true, null, false, false, false),
  ('GOV_BOARD_GENDER', (select id from dimensions where code = 'GOV'), 'Mixité du conseil', 'quantitative', 'higher_better', false, null, 0.7, '%', '% de femmes au conseil.', false, null, false, true, false),
  ('GOV_BOARD_INDEP', (select id from dimensions where code = 'GOV'), 'Administrateurs indépendants', 'quantitative', 'higher_better', false, null, 1, '%', '% d''administrateurs indépendants (doc AMF/URD), percentile intra-secteur.', false, null, false, true, false),
  ('GOV_SANCTIONS', (select id from dimensions where code = 'GOV'), 'Sanctions d''une autorité (concurrence, données personnelles, consommateurs)', 'categorical', 'higher_better', false, null, 0.9, 'controverse', 'Décision officielle d''une autorité de moins de 5 ans (concurrence, marchés numériques, données personnelles, consommateurs) : amende d''au moins 1 Md€ = sévérité 0,9 ; de 100 M€ à 1 Md€ = 0,7 ; moins de 100 M€ = 0,5. Plusieurs décisions : la plus grave compte. Absent : non pénalisé.', false, null, true, true, false),
  ('INV_CONTROVERSIAL_HOLDINGS', (select id from dimensions where code = 'INV'), 'Participations dans des secteurs controversés', 'quantitative', 'lower_better', false, null, 0.8, 'count', 'Nb de participations dans des secteurs controversés (armes, fossile...), percentile inversé.', false, null, true, true, false),
  ('INV_FOSSIL_FINANCING', (select id from dimensions where code = 'INV'), 'Liens financiers avec les énergies fossiles', 'quantitative', 'lower_better', false, null, 1, 'Md$', 'Financement annuel des entreprises qui développent de nouveaux projets pétroliers et gaziers (BOCC : amont + transport/GNL + centrales à gaz), en Md$. Valeur brute, percentile inversé intra-secteur.', false, null, false, true, false),
  ('INV_RESPONSIBLE_POLICY', (select id from dimensions where code = 'INV'), 'Politique d''investissement responsable', 'categorical', 'higher_better', false, null, 0.9, 'status', 'Absente/politique/signataire UN PRI vérifié -> 0/0.5/1.', false, null, false, true, false),
  ('INV_SOLIDARITY_LABEL', (select id from dimensions where code = 'INV'), 'Épargne solidaire labellisée (Finansol)', 'binary', 'higher_better', true, (select id from sectors where code = 'banking_finance'), 0.6, 'bool', 'Au moins un produit d''épargne distribué par l''établissement porte le label Finansol (liste officielle FAIR). Absence non renseignée (jamais comptée 0).', true, null, false, false, false),
  ('INV_SUSTAINABLE_FINANCE', (select id from dimensions where code = 'INV'), 'Finance durable (green / sustainability-linked bonds)', 'categorical', 'higher_better', false, null, 0.8, 'status', 'Aucun/émissions ponctuelles/cadre structuré -> 0/0.5/1.', false, null, true, true, false),
  ('LAB_CEO_PAY_RATIO', (select id from dimensions where code = 'LAB'), 'Écart de rémunération dirigeant / salarié médian', 'quantitative', 'lower_better', false, null, 1, 'ratio', 'Ratio DPEF/CSRD S1, percentile inversé intra-secteur.', false, null, true, true, false),
  ('LAB_EGAPRO_INDEX', (select id from dimensions where code = 'LAB'), 'Index égalité femmes-hommes (Égapro)', 'quantitative', 'higher_better', false, null, 1, 'score/100', 'Index Égapro FR /100 -> [0,1].', false, 'FR', false, false, false),
  ('LAB_GENDER_PAYGAP', (select id from dimensions where code = 'LAB'), 'Écart de salaire femmes-hommes', 'quantitative', 'closer_to_zero', false, null, 0.8, '%', 'Écart de rémunération femmes-hommes non ajusté (ESRS S1-16) ; rang intra-secteur de l''écart absolu : l''égalité (0 %) est le meilleur rang, quel que soit le sens de l''écart.', false, null, true, true, false),
  ('LAB_LITIGATION_RATE', (select id from dimensions where code = 'LAB'), 'Contentieux prud''homaux', 'quantitative', 'lower_better', false, null, 0.6, 'count/1000', 'Nb contentieux normalisé par effectif, percentile inversé.', false, null, true, true, false),
  ('LAB_LIVING_WAGE', (select id from dimensions where code = 'LAB'), 'Salaire décent interne', 'categorical', 'higher_better', false, null, 0.8, 'status', 'none/policy/verified -> 0/0.5/1.', false, null, true, true, false),
  ('PLA_POLLUTER', (select id from dimensions where code = 'PLA'), 'Pollueur plastique (Break Free From Plastic)', 'categorical', 'higher_better', false, null, 0, 'rang', 'Présence dans le top des pollueurs plastique mondiaux (audits de marques BFFP).', false, null, false, true, false),
  ('PLA_RECYCLED', (select id from dimensions where code = 'PLA'), 'Part d''emballages recyclés / réutilisables', 'quantitative', 'higher_better', false, null, 0.8, '%', 'Part d''emballages en matière recyclée ou réellement réutilisable/recyclable.', false, null, true, true, false),
  ('PLA_REDUCTION', (select id from dimensions where code = 'PLA'), 'Évolution réelle du plastique vierge', 'quantitative', 'lower_better', false, null, 1, '%/an', 'Rythme annuel moyen d''évolution du tonnage de plastique vierge publié par l''entreprise (rapport légal, ou à défaut rapport volontaire), entre l''année de référence et la dernière année publiée : r = (1 + variation)^(1/années) − 1. Une baisse ne compte que sur deux ans au moins. Classé entre pairs du secteur : la baisse la plus rapide obtient la meilleure note. Tonnage absolu seulement (pas par unité vendue).', false, null, true, true, false),
  ('SUP_BHRRC_ALLEG', (select id from dimensions where code = 'SUP'), 'Allégations d''atteintes aux droits humains', 'quantitative', 'lower_better', false, null, 0.6, 'count', 'Nb allégations BHRRC sur 5 ans (source presse, poids bas), percentile inversé.', false, null, true, true, false),
  ('SUP_FTI_SCORE', (select id from dimensions where code = 'SUP'), 'Fashion Transparency Index', 'quantitative', 'higher_better', true, (select id from sectors where code = 'fashion_leather'), 1, 'score/250', 'Score FTI /250 -> [0,1].', false, null, true, false, false),
  ('SUP_KNOWTHECHAIN', (select id from dimensions where code = 'SUP'), 'Lutte contre le travail forcé (KnowTheChain)', 'quantitative', 'higher_better', false, null, 1, 'score/100', 'Score KnowTheChain /100 -> [0,1].', false, null, true, true, false),
  ('SUP_LIVING_WAGE', (select id from dimensions where code = 'SUP'), 'Salaire décent fournisseurs', 'categorical', 'higher_better', false, null, 0.9, 'status', 'Clean Clothes Campaign (Fashion Checker) : A = 100 % des usines fournisseurs versent un salaire vital (référence et salaires publiés usine par usine) = 1 ; B plus de 50 % = 0,75 ; C plus de 26 % = 0,5 ; D 1 à 25 % = 0,25 ; E aucun salaire vital versé ni revendiqué = 0. Liste fermée : absent = non évalué.', false, null, true, true, false),
  ('SUP_SUPPLIER_LIST', (select id from dimensions where code = 'SUP'), 'Publication liste fournisseurs', 'binary', 'higher_better', false, null, 0.7, 'bool', 'Liste des sites de production publiée (oui/non). Hors mode et luxe : dans ces secteurs, la publication des fournisseurs est déjà évaluée par l''indice de transparence de la mode (Fashion Transparency Index) ; elle n''est pas comptée deux fois.', false, null, true, true, false),
  ('SUP_VIGILANCE_PLAN', (select id from dimensions where code = 'SUP'), 'Plan de vigilance (devoir de vigilance)', 'ordinal', 'higher_better', false, null, 1, 'level', 'Loi FR 2017 : absent/partiel/cartographie+suivi -> 0/0.5/1.', false, 'FR', false, true, true),
  ('TAX_CBCR_PUBLISHED', (select id from dimensions where code = 'TAX'), 'Reporting fiscal pays par pays publié', 'binary', 'higher_better', false, null, 1, 'bool', 'Déclaration CbCR publique (oui/non).', false, null, true, true, true),
  ('TAX_EFFECTIVE_RATE', (select id from dimensions where code = 'TAX'), 'Taux effectif d''imposition', 'quantitative', 'higher_better', false, null, 0.8, '%', 'Taux effectif vs taux statutaire, percentile intra-secteur.', false, null, false, true, false),
  ('TAX_HAVEN_PRESENCE', (select id from dimensions where code = 'TAX'), 'Présence en juridictions à faible imposition', 'quantitative', 'lower_better', false, null, 1, 'count', 'Nb d''entités en juridictions listées (Tax Justice Network), percentile inversé.', false, null, true, true, false),
  ('WAT_CDP', (select id from dimensions where code = 'WAT'), 'Sécurité de l''eau (CDP Water)', 'ordinal', 'higher_better', false, null, 1, 'grade', 'Note CDP Water Security (A à D-).', false, null, false, true, false),
  ('WAT_CONTROVERSY', (select id from dimensions where code = 'WAT'), 'Gestion de l''eau / stress hydrique', 'categorical', 'higher_better', false, null, 0.9, 'status', 'Prélèvements en zones de stress hydrique, controverses d''accaparement, gestion.', false, null, true, true, false),
  ('WAT_INTENSITY', (select id from dimensions where code = 'WAT'), 'Intensité de prélèvement d''eau', 'quantitative', 'lower_better', false, null, 0.8, 'm³/M€', 'Prélèvements d''eau rapportés au chiffre d''affaires, normalisés face aux pairs du secteur.', false, null, true, true, false)
